/**
 * Swipe to answer on this device (meta `swipe`): the Settings switch and how
 * far the coach has got. Never synced: it is about how practice feels on
 * this screen, like "After an answer".
 *
 * Every write reads inside the same transaction, so two cards counting at
 * once (or two tabs) never lose one of the counts.
 */
import { db, getMeta, setMeta, type StoredSwipe } from '@/db/schema.js';

/** What a device that never wrote anything gets: swiping on, nothing taught yet. */
export const SWIPE_DEFAULT: StoredSwipe = {
  off: false,
  backDemos: 0,
  frontLines: 0,
  swiped: false,
  swipedFront: false,
};

/** Reads a stored value; anything missing or malformed is the default. */
export function swipeOf(value: unknown): StoredSwipe {
  if (value === null || typeof value !== 'object') return SWIPE_DEFAULT;
  const stored = value as Partial<StoredSwipe>;
  const count = (n: unknown): number => (typeof n === 'number' && Number.isFinite(n) && n > 0 ? n : 0);
  return {
    off: stored.off === true,
    backDemos: count(stored.backDemos),
    frontLines: count(stored.frontLines),
    swiped: stored.swiped === true,
    swipedFront: stored.swipedFront === true,
  };
}

/** This device's swipe state. */
export async function loadSwipe(): Promise<StoredSwipe> {
  return swipeOf(await getMeta('swipe'));
}

/**
 * Writes only a real change: every write wakes the live queries that read
 * meta, and a swipe already learnt redrew the whole session on each card.
 */
async function change(update: (state: StoredSwipe) => StoredSwipe): Promise<void> {
  await db.transaction('rw', db.meta, async () => {
    const state = swipeOf(await getMeta('swipe'));
    const next = update(state);
    if (next !== state) await setMeta('swipe', next);
  });
}

/** Settings → Practice → "Swipe to answer". */
export async function setSwipeOff(off: boolean): Promise<void> {
  await change((state) => ({ ...state, off }));
}

/** A card was graded by a swipe: the coach's lessons are learnt. */
export async function noteSwiped(fromFront: boolean): Promise<void> {
  await change((state) =>
    state.swiped && (state.swipedFront || !fromFront)
      ? state
      : { ...state, swiped: true, swipedFront: state.swipedFront || fromFront },
  );
}

/** A coach step was shown in this run; each counts once per run, by its caller. */
export async function noteCoach(step: 'back' | 'front'): Promise<void> {
  await change((state) =>
    step === 'back'
      ? { ...state, backDemos: state.backDemos + 1 }
      : { ...state, frontLines: state.frontLines + 1 },
  );
}
